import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSegmented,
  JxSelect,
  JxSlider,
  JxSwitch,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEMES: { value: Theme; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'jetbrains-mono', label: 'JetBrains Mono' },
  { value: 'georgia', label: 'Georgia' },
];

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const commit = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    THEMES.find((t) => t.value === settings.theme)?.label ?? settings.theme;

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 style={{ margin: 0 }}>Внешний вид</h2>
        <JxBadge>{themeLabel}</JxBadge>
      </header>

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-2)',
        }}
      >
        <label htmlFor="appearance-theme">Тема</label>
        <JxSegmented
          id="appearance-theme"
          options={THEMES}
          value={settings.theme}
          onValueChange={(value: Theme) => commit({ theme: value })}
        />
      </div>

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-2)',
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 'var(--jx-space-3)',
          }}
        >
          <label htmlFor="appearance-scale">Масштаб интерфейса</label>
          <span>{settings.scale}%</span>
        </div>
        <JxSlider
          id="appearance-scale"
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value: number) => commit({ scale: value })}
        />
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <label htmlFor="appearance-dense">Плотная вёрстка</label>
        <JxSwitch
          id="appearance-dense"
          checked={settings.dense}
          onCheckedChange={(checked: boolean) => commit({ dense: checked })}
        />
      </div>

      <JxDivider />

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h3 style={{ margin: 0 }}>Ещё</h3>
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-2)',
          }}
        >
          <label htmlFor="appearance-font">Шрифт</label>
          <JxSelect
            id="appearance-font"
            options={FONTS}
            value={settings.fontFamily}
            onValueChange={(value: string) => commit({ fontFamily: value })}
          />
        </div>
      </div>
    </section>
  );
}

export default AppearanceSettingsScreen;

